from calendar import monthrange
from datetime import date, timedelta


def recur(start: str, rule: str, count: int) -> list[str]:
    first = date.fromisoformat(start)
    parts = rule.split()
    kind = parts[0]
    step = int(parts[1])
    weekdays = {
        code: i
        for i, code in enumerate(("MO", "TU", "WE", "TH", "FR", "SA", "SU"))
    }

    if kind == "DAILY":
        return [
            (first + timedelta(days=i * step)).isoformat()
            for i in range(count)
        ]

    result = []

    if kind == "WEEKLY":
        selected = sorted(weekdays[code] for code in parts[2].split(","))
        monday = first - timedelta(days=first.weekday())

        while True:
            for weekday in selected:
                candidate = monday + timedelta(days=weekday)
                if candidate >= first:
                    result.append(candidate.isoformat())
                    if len(result) == count:
                        return result
            monday += timedelta(weeks=step)

    if kind == "MONTHLY":
        month_index = first.year * 12 + first.month - 1
        selector = int(parts[2])
        weekday = weekdays[parts[3]] if len(parts) == 4 else None

        while True:
            year, month_zero = divmod(month_index, 12)
            month = month_zero + 1
            first_weekday, last_day = monthrange(year, month)

            if weekday is None:
                day = last_day if selector == -1 else selector
            elif selector == -1:
                day = last_day - (
                    (first_weekday + last_day - 1 - weekday) % 7
                )
            else:
                day = 1 + (weekday - first_weekday) % 7 + 7 * (selector - 1)

            if day <= last_day:
                candidate = date(year, month, day)
                if candidate >= first:
                    result.append(candidate.isoformat())
                    if len(result) == count:
                        return result

            month_index += step

    if kind == "YEARLY":
        month, day = map(int, parts[2].split("-"))
        year = first.year

        while True:
            if day <= monthrange(year, month)[1]:
                candidate = date(year, month, day)
                if candidate >= first:
                    result.append(candidate.isoformat())
                    if len(result) == count:
                        return result
            year += step
